✔ 문제 제목: 크레인 인형뽑기

✔ 문제 유형: stack

✔ 문제 풀이 날짜: 09.13

## 💡 문제 분석 요약

- 이차원배열 순회와 stack을 사용

## 💡 알고리즘 설계

- 이중 for문으로 이차원 배열 순회

## 💡코드

```javascript
function solution(board, moves) {
  let answer = 0;
  let stack = [];
  let array = [...board];

  for (let i of moves) {
    for (let arr of array) {
      let val = arr[i - 1];
      if (val) {
        if (stack[stack.length - 1] === val) {
          stack.pop();
          answer += 2;
        } else {
          stack.push(arr[i - 1]);
        }
        arr[i - 1] = 0;
        break;
      }
    }
  }

  return answer;
}

let a = [
  [0, 0, 0, 0, 0],
  [0, 0, 1, 0, 3],
  [0, 2, 5, 0, 1],
  [4, 2, 4, 4, 2],
  [3, 5, 1, 3, 1],
];

let b = [1, 5, 3, 5, 1, 2, 1, 4];
console.log(solution(a, b));

```

## 💡 틀린 이유와 틀린 부분 수정 or 다른 풀이

- for문을 한번만 사용해서 풀수 있는데 코드가 잘 이해가 안되네요

```javascript
const transpose = matrix =>
    matrix.reduce(
        (result, row) => row.map((_, i) => [...(result[i] || []), row[i]]),
        []
    );

const solution = (board, moves) => {
    const stacks = transpose(board).map(row =>
        row.reverse().filter(el => el !== 0)
    );
    const basket = [];
    let result = 0;

    for (const move of moves) {
        const pop = stacks[move - 1].pop();
        if (!pop) continue;
        if (pop === basket[basket.length - 1]) {
            basket.pop();
            result += 2;
            continue;
        }
        basket.push(pop);
    }

    return result;
};
```

